create or replace function public.app_admin_financeiro(p_token text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare v record; begin select * into v from public.app_tenant_usuario(p_token) limit 1; if v.perfil not in('admin','administrador','gestor') then return jsonb_build_object('sucesso',false,'erro','Acesso negado'); end if; return jsonb_build_object('sucesso',true,'contas',(select coalesce(jsonb_agg(to_jsonb(x) order by x.vencimento),'[]'::jsonb) from (select id,tipo,categoria,descricao,valor,vencimento,status,pago_em,observacoes from public.financeiro_lancamentos where empresa_id=v.empresa_id order by vencimento desc limit 500)x),'dividas',(select coalesce(jsonb_agg(to_jsonb(x) order by x.vencimento nulls last),'[]'::jsonb) from (select id,credor,descricao,valor_original,saldo_devedor,vencimento,status,observacoes from public.dividas_gestao where empresa_id=v.empresa_id limit 500)x),'recorrencias',(select coalesce(jsonb_agg(to_jsonb(x) order by x.proximo_vencimento),'[]'::jsonb) from (select id,descricao,categoria,fornecedor,valor,periodicidade,proximo_vencimento,ativo from public.financeiro_recorrencias where empresa_id=v.empresa_id limit 300)x),'parcelas',(select coalesce(jsonb_agg(to_jsonb(x) order by x.vencimento),'[]'::jsonb) from (select p.id,p.numero,p.valor,p.vencimento,p.status,p.pago_em,p.comprovante_nome,s.credor,s.descricao from public.financeiro_parcelas p join public.financeiro_parcelamentos s on s.id=p.parcelamento_id where p.empresa_id=v.empresa_id limit 1000)x)); end; $$;
grant execute on function public.app_admin_financeiro(text) to anon,authenticated;
